<?php declare(strict_types=1); require_once __DIR__.'/auth.php'; $user=require_role('victor','tester'); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beta | Agenda y seguimiento</title><link rel="stylesheet" href="style.css"><style>.beta-nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.beta-nav button{border:1px solid #cbd8e4;background:#fff;color:#1557a6;border-radius:4px;padding:11px 15px;font:600 13px inherit;cursor:pointer}.beta-nav button.active{background:#1557a6;color:#fff}.panel{background:#fff;border:1px solid #d6e0eb;padding:24px;box-shadow:8px 8px 0 #dceafb;margin-bottom:22px}.panel h2{margin-top:0}.tab{display:none}.tab.active{display:block}.days{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.day{border:1px solid #d6e0eb;padding:12px}.day label{display:flex;gap:8px;align-items:center;font-weight:700}.day input[type=time]{padding:8px;border:1px solid #d6e0eb;margin-top:8px}.muted{color:#5b6b80;font-size:13px}.row{display:flex;gap:10px;flex-wrap:wrap}.row input,.row textarea{padding:10px;border:1px solid #d6e0eb;border-radius:3px;font:inherit}.row textarea{width:100%;min-height:100px}.appointment{border-left:3px solid #1557a6;padding:12px;background:#f4f7fb;margin:10px 0}.status{min-height:20px;color:#1557a6}@media(max-width:700px){.days{grid-template-columns:1fr}.panel{padding:18px}.row>*{width:100%}}</style></head><body><header class="topbar"><div><p class="eyebrow">LIBERATE DE TUS DEUDAS.CL</p><h1>Beta: Agenda y seguimiento</h1></div><div class="account"><span><?=htmlspecialchars($user['username'])?></span><a href="index.php?logout=1">Salir</a></div></header><main class="wrap"><div class="beta-nav"><button class="active" data-tab="agenda">Agenda</button><button data-tab="horarios">Horarios</button><button data-tab="resumen">Resumen de cliente</button></div><section id="agenda" class="tab active panel"><h2>Agenda de Víctor</h2><p class="muted">Beta local. Todavía no crea eventos en Google Calendar.</p><form id="appointment-form"><div class="row"><input name="phone" placeholder="Teléfono +56..." required><input name="title" placeholder="Título de la cita" required><input name="starts_at" type="datetime-local" required><input name="ends_at" type="datetime-local" required></div><p><button class="button" type="submit">Guardar cita de prueba</button></p><div class="status" id="appointment-status"></div></form><div id="appointments">Cargando citas...</div></section><section id="horarios" class="tab panel"><h2>Horarios disponibles</h2><p class="muted">Estas reglas serán usadas después para ofrecer horas libres por WhatsApp.</p><div class="days" id="days"></div><p><button class="button" id="save-settings">Guardar horarios</button></p><div class="status" id="settings-status"></div></section><section id="resumen" class="tab panel"><h2>Resumen de cliente</h2><p class="muted">Escribe un resumen de prueba. Más adelante el agente podrá proponerlo automáticamente para revisión.</p><form id="summary-form"><div class="row"><input name="phone" placeholder="Teléfono del cliente" required><textarea name="summary" placeholder="Situación, necesidad y próximo paso" required></textarea><input name="next_action" placeholder="Próxima acción"></div><p><button class="button" type="submit">Guardar resumen</button></p><div class="status" id="summary-status"></div></form></section></main><script>const csrf=<?=json_encode(csrf_token())?>;const daysNames=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];async function api(url,opts={}){opts.headers={...(opts.headers||{}),'X-CSRF-Token':csrf,'Content-Type':'application/json'};const r=await fetch(url,opts),d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo completar');return d}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.beta-nav button,.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')});async function loadSettings(){const d=await api('api/settings.php');document.querySelector('#days').innerHTML=d.data.map(x=>`<div class="day"><label><input type="checkbox" data-day="${x.weekday}" ${+x.enabled?'checked':''}> ${daysNames[x.weekday-1]}</label><input data-start="${x.weekday}" type="time" value="${x.start_time||'09:00:00'}"><input data-end="${x.weekday}" type="time" value="${x.end_time||'18:00:00'}"></div>`).join('')}async function loadAppointments(){const d=await api('api/appointments.php');document.querySelector('#appointments').innerHTML=d.data.map(x=>`<article class="appointment"><b>${x.title}</b><br>${x.phone}<br>${x.starts_at} - ${x.ends_at}<br><span class="muted">${x.status}</span></article>`).join('')||'<p class="muted">No hay citas de prueba.</p>'}document.querySelector('#save-settings').onclick=async()=>{const days=[...document.querySelectorAll('[data-day]')].map(c=>({weekday:+c.dataset.day,enabled:c.checked,start_time:document.querySelector(`[data-start="${c.dataset.day}"]`).value,end_time:document.querySelector(`[data-end="${c.dataset.day}"]`).value,slot_minutes:30,buffer_minutes:10}));try{await api('api/settings.php',{method:'POST',body:JSON.stringify({days})});document.querySelector('#settings-status').textContent='Horarios guardados.'}catch(e){document.querySelector('#settings-status').textContent=e.message}};document.querySelector('#appointment-form').onsubmit=async e=>{e.preventDefault();try{await api('api/appointments.php',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();document.querySelector('#appointment-status').textContent='Cita guardada.';loadAppointments()}catch(x){document.querySelector('#appointment-status').textContent=x.message}};document.querySelector('#summary-form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));try{await api('api/summary.php?phone='+encodeURIComponent(p.phone),{method:'POST',body:JSON.stringify(p)});document.querySelector('#summary-status').textContent='Resumen guardado.'}catch(x){document.querySelector('#summary-status').textContent=x.message}};loadSettings();loadAppointments();</script></body></html>
